window.createWarriorController=function(T,world,api){
 const held=new Set(),actions={};let actor,mixer,current,busy=0,pending=null,lastTarget=null,route=[],destinationObject=null,running=false,orderVersion=0,nearObject=null,nearSelection=null,impact=null,impactAt=0,slowUntil=0,clock=0,pushMotion=null;
 const container=new T.Group();world.add(container);
 const state=()=>api.state(),enabled=()=>api.active()&&state()?.phase!=='waveDialogue'&&state()?.screen==='game'&&!state().ui.openModal&&!state().ui.placing&&!document.querySelector('.screen-curtain');
 const objectBoxes=new WeakMap();
 const names={hut:'Дом',chapel:'Церковь',well:'Колодец',oven:'Печь',tower:'Дозорная башня',circle:'Ритуальный круг',totem:'Оберег',lantern:'Фонарь',woodpile:'Поленница'};
 function play(name,once=false){const next=actions[name]||actions.Idle;if(!next||next===current)return;next.reset().setLoop(once?T.LoopOnce:T.LoopRepeat,once?1:Infinity);next.clampWhenFinished=once;next.play();if(current)current.crossFadeTo(next,.22,false);current=next;}
 function objectDistance(obj){if(!obj.visible||!obj.parent)return Infinity;let box=objectBoxes.get(obj);if(!box||obj.userData.movingActor){obj.updateMatrixWorld(true);box=new T.Box3();obj.traverse(o=>{if(o.isMesh&&!o.userData.navigationIgnore)box.union(new T.Box3().setFromObject(o))});objectBoxes.set(obj,box)}const p=container.position;return Math.hypot(Math.max(box.min.x-p.x,0,p.x-box.max.x),Math.max(box.min.z-p.z,0,p.z-box.max.z))}
 function nearbyObjects(){return api.objects().filter(o=>objectDistance(o)<2.4).sort((a,b)=>objectDistance(a)-objectDistance(b))}
 function nearest(){if(nearSelection&&objectDistance(nearSelection)<3.1){nearObject=nearSelection;return nearObject}nearSelection=null;const best=nearbyObjects()[0]||null;if(nearObject&&objectDistance(nearObject)<3.1&&(!best||objectDistance(best)+.65>=objectDistance(nearObject)))return nearObject;nearObject=best;return best}
 function interact(target){if(!actor||busy||!enabled())return;const obj=target||nearest();if(!obj||!obj.parent||!obj.visible)return;const info=obj.userData.villageObject;container.rotation.y=Math.atan2(obj.position.x-container.position.x,obj.position.z-container.position.z);play(['hut','chapel','chest_cloth'].includes(info.id)?'Push':'Inspect',true);busy=['hut','chapel','chest_cloth'].includes(info.id)?1.65:1.2;pending=()=>{if(obj.visible&&obj.parent)api.select({...info})};held.clear();}
 async function order(point,obj=null,run=false){if(!enabled()||!actor)return;const version=++orderVersion;route=[];destinationObject=null;running=run;busy=0;pending=null;impact=null;api.target?.(null);const goal={x:point.x,z:point.z};const path=await api.findPath(container.position,goal,true,()=>version!==orderVersion||!enabled());if(version!==orderVersion||!enabled())return;if(!path){api.error('До этого места не пройти. Выбери другую точку.');return}route=path;api.target?.(path.target,path.approximate);if(path.approximate)api.error('Подойду настолько близко, насколько возможно.');}
 window.addEventListener('blur',()=>{orderVersion++;route=[];destinationObject=null;api.target?.(null)});
 new T.GLTFLoader().load('assets/warrior/warrior.glb',gltf=>{actor=gltf.scene;const bounds=new T.Box3().setFromObject(actor),size=bounds.getSize(new T.Vector3()),center=bounds.getCenter(new T.Vector3()),body=new T.Group();body.scale.setScalar(1.9/size.y);actor.position.set(-center.x,-bounds.min.y,-center.z);body.add(actor);container.add(body);actor.traverse(o=>{if(o.isMesh){o.castShadow=o.receiveShadow=true;o.frustumCulled=false;for(const m of(Array.isArray(o.material)?o.material:[o.material]))api.material(m)}});mixer=new T.AnimationMixer(actor);for(const clip of gltf.animations)actions[clip.name]=mixer.clipAction(clip);for(const [key,name] of Object.entries({Idle:'Idle_Breathing',Walk:'Walk_InPlace',Run:'Run_InPlace',Inspect:'Point',Push:'Talk'}))if(!actions[key])actions[key]=actions[name];const meta=gltf.parser?.json?.animations||[];for(const name of ['Walk','Run']){const speed=meta.find(c=>c.name===name)?.extras?.speed;if(speed&&actions[name])actions[name].setEffectiveTimeScale((name==='Run'?3.6:1.7)/(speed*body.scale.x))}const p=state().hero.scenePosition||{x:1.8,z:-2};container.position.set(p.x,api.height(p.x,p.z),p.z);play('Idle');},undefined,()=>api.error('Не удалось загрузить богатыря. Обнови страницу.'));
 function sync(){orderVersion++;nearObject=nearSelection=null;api.target?.(null);route=[];destinationObject=null;held.clear();pending=null;impact=null;pushMotion=null;busy=0;const p=state().hero.scenePosition||{x:1.8,z:-2};container.position.set(p.x,api.height(p.x,p.z),p.z);play('Idle');}
 function tick(dt){clock+=dt;if(!actor)return;if(pushMotion&&enabled()){const p=container.position,step=Math.min(dt,pushMotion.left)*pushMotion.speed,x=p.x+pushMotion.dx*step,z=p.z+pushMotion.dz*step;if(api.walkable(x,z,p.y,p.x,p.z)){p.set(x,api.height(x,z,p.y),z);state().hero.scenePosition={x:p.x,z:p.z};api.follow(p,dt)}else pushMotion.left=0;pushMotion.left-=dt;if(pushMotion.left<=0)pushMotion=null}if(!enabled()){orderVersion++;api.target?.(null);route=[];destinationObject=null;held.clear();busy=0;pending=null;impact=null;play(state().hero.hp>0?'Idle':'Death',state().hero.hp<=0);mixer.update(dt);const hint=document.getElementById('warrior-hint');if(hint)hint.hidden=true;return}if(busy>0){busy-=dt;impactAt-=dt;if(impact&&impactAt<=0){const fn=impact;impact=null;fn()}if(busy<=0){const fn=pending;pending=null;fn?.();play('Idle')}mixer.update(dt);return}
 const p=container.position;while(route.length&&Math.hypot(route[0].x-p.x,route[0].z-p.z)<.09)route.shift();const target=route[0],run=running;let moved=false;
 if(target){const vx=target.x-p.x,vz=target.z-p.z,len=Math.hypot(vx,vz),dx=vx/len,dz=vz/len,step=Math.min(len,(run?3.6:1.7)*(slowUntil>clock?.45:1)*dt),x=p.x+dx*step,z=p.z+dz*step;if(api.walkable(x,z,p.y,p.x,p.z)){p.set(x,api.height(x,z,p.y),z);moved=true;const angle=Math.atan2(dx,dz),diff=Math.atan2(Math.sin(angle-container.rotation.y),Math.cos(angle-container.rotation.y));container.rotation.y+=diff*Math.min(1,dt*12);state().hero.scenePosition={x:p.x,z:p.z};api.follow(p,dt)}else{route=[];destinationObject=null;api.target?.(null);api.error('Путь перекрыт. Выбери другую точку.')}}else if(destinationObject){const obj=destinationObject;destinationObject=null;interact(obj);}
 if(!route.length)api.target?.(null);play(moved?(run?'Run':'Walk'):'Idle');mixer.update(dt);

 }
 return {tick,sync,order,work(onFinish){if(!actor||!enabled()||busy>0)return false;route=[];orderVersion++;api.target?.(null);play('Inspect',true);busy=1.6;pending=onFinish;impact=null;held.clear();return true},strike(point,onImpact){if(!enabled()||busy>0)return false;route=[];orderVersion++;api.target?.(null);container.rotation.y=Math.atan2(point.x-container.position.x,point.z-container.position.z);const name=['Attack','Attack3','Attack4'][Math.floor(clock)%3];play(name,true);busy=1.35;impactAt=.7;impact=onImpact||null;pending=null;return true},react(){if(!actor)return;impact=null;play(state().hero.hp>0?'Hit':'Death',true);busy=state().hero.hp>0?1.1:3;pending=null},slow(seconds){slowUntil=clock+seconds},push(dx,dz,distance=1.5){if(!enabled())return;route=[];orderVersion++;impact=null;api.target?.(null);const len=Math.hypot(dx,dz)||1;pushMotion={dx:dx/len,dz:dz/len,speed:distance/.24,left:.24};this.react()},position:()=>container.position,nearby:nearest,nearbyObjects,chooseNearby:obj=>{nearSelection=nearObject=obj},ready:()=>!!actor};
};
